import test from'node:test';import assert from'node:assert/strict';
import {decimal,pack,units,format,small,exactInt}from'../math.mjs';import {injectiveMarket,hyperMarket,normalizeBook}from'../market.mjs';import {demoInputs,DEMO_MARKET}from'../demo.mjs';import {NOW}from'./fixtures.mjs';
const data=()=>demoInputs(NOW),inj=x=>injectiveMarket(x,'test',DEMO_MARKET),hyp=x=>hyperMarket(x,'test',1);
test('decimal and atomic conversions never round through Number',()=>{assert.deepEqual(pack(decimal('1.0000000000000001')),{numerator:'10000000000000001',denominator:'10000000000000000'});assert.equal(units('9007199254740993',18),9007199254740993000000000000000000n);assert.equal(format('1234567',6),'1.234567');});
test('bounded scientific strings remain exact, never underflow to zero',()=>{assert.equal(units('1e-6',6),1n);assert.throws(()=>units('1e-7',6),/FRACTIONAL_ATOM/);assert.throws(()=>decimal('1e-9999'),/DECIMAL/);});
test('malformed, signed and extremely long amounts are rejected',()=>{for(const s of ['-1','+1','NaN','Infinity','01','1.','1e','0'.repeat(161),1])assert.throws(()=>decimal(s));});
test('timestamp accepts exact thirteen digit strings without losing precision',()=>assert.equal(small(String(NOW),Number.MAX_SAFE_INTEGER),NOW));
test('Injective chain price and lot remain quote-atoms per base-atom',()=>{const m=inj(data().market);assert.equal(m.base.decimals,18);assert.deepEqual(m.priceTick,{numerator:'1',denominator:'1000000000000'});assert.equal(m.lotAtomic,'10000000000000000');});
test('Injective market mismatch and paused market cannot become quotes',()=>{const x=data().market;assert.throws(()=>inj({...x,marketId:'0x'+'11'.repeat(32)}),/MARKET_ID/);assert.throws(()=>inj({...x,marketStatus:'paused'}),/INACTIVE/);});
test('Injective zero lot, negative fee, fee over one and fractional atomic lot fail closed',()=>{for(const m of [{minQuantityTickSize:'0'},{minQuantityTickSize:'0.1'},{takerFeeRate:'-0.01'},{takerFeeRate:'1.01'}])assert.throws(()=>inj({...data().market,...m}));});
test('same asset on both sides and invalid decimals rejected',()=>{const m=data().market;assert.throws(()=>inj({...m,quoteDenom:m.baseDenom}),/IDENTICAL/);m.baseTokenMeta.decimals='37';assert.throws(()=>inj(m),/RANGE/);});
test('HyperCore uses tokenId and pair index, not a display ticker or EVM address',()=>{const m=hyp(data().hyperMeta);assert.match(m.base.id,/22222222/);assert.equal(m.coin,'@1');assert.equal(m.lotAtomic,'1000000');assert.equal(m.takerFeeRate,null);assert.equal(m.balanceLocation,'hypercore:test:spot');});
test('HyperCore excludes bare perpetual coin symbols',()=>{const x=data().hyperMeta;x.universe[0].name='DEMO';assert.throws(()=>hyp(x),/SPOT_ONLY/);});
test('duplicate token and pair indices are rejected',()=>{for(const field of ['tokens','universe']){const x=data().hyperMeta;x[field].push(x[field][0]);assert.throws(()=>hyp(x),/DUPLICATE/);}});
test('HyperCore duplicate token IDs, missing tokens and inverted decimals rejected',()=>{const x=data().hyperMeta;x.tokens[1].tokenId=x.tokens[0].tokenId;assert.throws(()=>hyp(x),/IDENTICAL/);const y=data().hyperMeta;y.universe[0].tokens=[1,8];assert.throws(()=>hyp(y),/MAPPING/);const z=data().hyperMeta;z.tokens[1].szDecimals=8;z.tokens[1].weiDecimals=6;assert.throws(()=>hyp(z),/PRECISION/);});
test('Injective uint64 sequence survives greater-than-safe-integer values',()=>{const x=data();const b=normalizeBook(inj(x.market),x.book,{receivedAt:NOW});assert.equal(b.sourceSequence,'9007199254740993');assert.equal(b.executable,false);});
test('stale or future-dated books are not silently freshened',()=>{for(const delta of [-30001,2001]){const x=data();x.book.timestamp=String(NOW+delta);assert.throws(()=>normalizeBook(inj(x.market),x.book,{receivedAt:NOW}),/STALE/);}});
test('unsorted and duplicate price levels rejected instead of sorted into validity',()=>{for(const same of [false,true]){const x=data();x.book.buys.reverse();if(same)x.book.buys[1].price=x.book.buys[0].price;assert.throws(()=>normalizeBook(inj(x.market),x.book,{receivedAt:NOW}),/BOOK_ORDER/);}});
test('crossed book does not create an apparent arbitrage',()=>{const x=data();x.book.buys[0].price='0.000000000012';assert.throws(()=>normalizeBook(inj(x.market),x.book,{receivedAt:NOW}),/CROSSED/);});
test('quantity granularity and price tick violations rejected',()=>{for(const change of [{quantity:'1'},{price:'0.0000000000105'}]){const x=data();Object.assign(x.book.buys[0],change);assert.throws(()=>normalizeBook(inj(x.market),x.book,{receivedAt:NOW}));}});
test('limited depth and no liquidity are represented without fabricated orders',()=>{const x=data();x.book.buys=[];x.book.sells=[];assert.deepEqual(normalizeBook(inj(x.market),x.book,{receivedAt:NOW}).bids,[]);x.book.buys=Array(101).fill({price:'1',quantity:'1'});assert.throws(()=>normalizeBook(inj(x.market),x.book,{receivedAt:NOW}),/DEPTH/);});
test('HyperCore human prices and sizes convert to atom units',()=>{const x=data(),b=normalizeBook(hyp(x.hyperMeta),x.hyperBook,{receivedAt:NOW});assert.deepEqual(b.bids[0].price,{numerator:'1',denominator:'10'});assert.equal(b.bids[0].baseAtomic,'50000000');});
test('HyperCore rejects wrong coin, excessive price precision and zero order count',()=>{for(const k of ['coin','price','count']){const x=data();if(k==='coin')x.hyperBook.coin='ETH';else if(k==='price')x.hyperBook.levels[0][0].px='10.00001';else x.hyperBook.levels[0][0].n=0;assert.throws(()=>normalizeBook(hyp(x.hyperMeta),x.hyperBook,{receivedAt:NOW}));}});
